/** 
 * Generate a new certificate with new key pair
 * @return
 */
@POST @NoCache @Path("generate") @Produces(MediaType.APPLICATION_JSON) public CertificateRepresentation generate(){
  try {
    auth.requireManage();
    if (client == null) {
      throw new NotFoundException("Could not find client");
    }
    CertificateRepresentation info = KeycloakModelUtils.generateKeyPairCertificate(client.getClientId());
    client.setAttribute(privateAttribute, info.getPrivateKey());
    client.setAttribute(certificateAttribute, info.getCertificate());
    adminEvent.operation(OperationType.ACTION).resourcePath(session.getContext().getUri()).representation(info).success();
    return info;
  } catch (RuntimeException e) {
    // Log the exception and rethrow or handle it appropriately
    throw new RuntimeException("Error generating certificate: " + e.getMessage(), e);
  }
}
